-- SRT_SUPPLIES · Sorter · L1427–1440 · dropped: row order means nothing in a table (decision Q12)
-- AGG_SUPPLIES_BY_PRODUCT · Aggregator · L1441–1453
agg_supplies_by_product as (
    select
        sq_stg_supplies.product_id,
        sum(sq_stg_supplies.supply_cost) as supply_cost_per_product,
        max(sq_stg_supplies.is_perishable) as has_perishable_supply
    from sq_stg_supplies
    group by sq_stg_supplies.product_id
),

-- JNR_ADD_SUPPLIES · Joiner · L1454–1485 · Master Outer Join
jnr_add_supplies as (
