        master.is_food_item,
        master.is_drink_item,
        master.customer_name,
        master.location_name,
        master.tax_rate,
        master.region,
        detail.supply_cost_per_product,
        detail.has_perishable_supply
    from agg_supplies_by_product as detail
    left join jnr_add_locations as master  -- FLAG master_outer L1476: JNR_ADD_SUPPLIES is a Master Outer Join: it keeps every row from AGG_SUPPLIES_BY_PRODUCT (detail) and only the rows from JNR_ADD_LOCATIONS (master) that match; JNR_ADD_LOCATIONS rows with no match are dropped
        on master.product_id = detail.product_id
),

-- EXP_ITEM_CALCULATIONS · Expression · L1486–1519
exp_item_calculations as (
    select
        jnr_add_supplies.order_item_id,
        jnr_add_supplies.order_id,
        jnr_add_supplies.product_id,
        jnr_add_supplies.customer_id,
        jnr_add_supplies.location_id,
        jnr_add_supplies.ordered_at_day,
        jnr_add_supplies.product_name,
        jnr_add_supplies.product_type,
        jnr_add_supplies.product_price,
        jnr_add_supplies.is_food_item,
        jnr_add_supplies.is_drink_item,
        case when (jnr_add_supplies.customer_name is null) then 'Unknown' else jnr_add_supplies.customer_name end as customer_name,
        case when (jnr_add_supplies.location_name is null) then 'Unknown' else jnr_add_supplies.location_name end as location_name,
        case when (jnr_add_supplies.region is null) then 'Unknown' else jnr_add_supplies.region end as region,
        jnr_add_supplies.product_price as item_revenue,
        /* v_SUPPLY_COST_CL L1511 */ (case when (jnr_add_supplies.supply_cost_per_product is null) then 0 else jnr_add_supplies.supply_cost_per_product end) as item_cogs,
        jnr_add_supplies.product_price - /* v_SUPPLY_COST_CL L1511 */ (case when (jnr_add_supplies.supply_cost_per_product is null) then 0 else jnr_add_supplies.supply_cost_per_product end) as item_gross_profit,
        /* v_MARGIN_CALC L1513 */ (case when jnr_add_supplies.product_price = 0 then 0 else (jnr_add_supplies.product_price - /* v_SUPPLY_COST_CL L1511 */ (case when (jnr_add_supplies.supply_cost_per_product is null) then 0 else jnr_add_supplies.supply_cost_per_product end)) / jnr_add_supplies.product_price end) as item_gross_margin_pct,
        jnr_add_supplies.product_price * /* v_TAX_RATE_CL L1510 */ (case when (jnr_add_supplies.tax_rate is null) then 0 else jnr_add_supplies.tax_rate end) as item_tax_estimate,
        jnr_add_supplies.product_price + (jnr_add_supplies.product_price * /* v_TAX_RATE_CL L1510 */ (case when (jnr_add_supplies.tax_rate is null) then 0 else jnr_add_supplies.tax_rate end)) as item_total_estimate,
        /* v_HAS_PERISHABLE_CL L1512 */ (case when (jnr_add_supplies.has_perishable_supply is null) then 0 else jnr_add_supplies.has_perishable_supply end) as has_perishable_supply
    from jnr_add_supplies
),

-- SRT_ORDER_ID · Sorter · L1520–1551 · dropped: row order means nothing in a table (decision Q12)
-- SRT_BEFORE_AGG_PDP · Sorter · L2130–2149 · dropped: row order means nothing in a table (decision Q12)
-- AGG_BY_PRODUCT_DAY · Aggregator · L2150–2171
agg_by_product_day as (
    select
        exp_item_calculations.product_id,
        exp_item_calculations.product_name,
        exp_item_calculations.product_type,
        exp_item_calculations.ordered_at_day,
        count(exp_item_calculations.order_item_id) as units_sold,
        sum(exp_item_calculations.item_revenue) as revenue,
        sum(exp_item_calculations.item_cogs) as cogs,
        sum(exp_item_calculations.item_gross_profit) as gross_profit,
        max(exp_item_calculations.has_perishable_supply) as perishable_sales_flag
    from exp_item_calculations
    group by exp_item_calculations.product_id, exp_item_calculations.product_name, exp_item_calculations.product_type, exp_item_calculations.ordered_at_day
),

-- EXP_PRODUCT_METRICS · Expression · L2172–2184
exp_product_metrics as (
    select
        agg_by_product_day.product_id,
        agg_by_product_day.product_name,
        agg_by_product_day.product_type,
        agg_by_product_day.ordered_at_day,
        agg_by_product_day.units_sold,
        agg_by_product_day.revenue,
        agg_by_product_day.cogs,
        agg_by_product_day.gross_profit,
        agg_by_product_day.perishable_sales_flag,
        case when agg_by_product_day.revenue = 0 then 0 else agg_by_product_day.gross_profit / agg_by_product_day.revenue end as margin_pct
    from agg_by_product_day
)

select
    cast(exp_product_metrics.product_id as varchar) as product_id,
    cast(exp_product_metrics.product_name as varchar) as product_name,
    cast(exp_product_metrics.product_type as varchar) as product_type,
    cast(exp_product_metrics.ordered_at_day as timestamp) as ordered_at_day,
    cast(exp_product_metrics.units_sold as decimal(15,0)) as units_sold,
    cast(exp_product_metrics.revenue as decimal(12,2)) as revenue,
    cast(exp_product_metrics.cogs as decimal(12,2)) as cogs,
    cast(exp_product_metrics.gross_profit as decimal(12,2)) as gross_profit,
    cast(exp_product_metrics.perishable_sales_flag as decimal(10,4)) as margin_pct,  -- FLAG crossed L2542: EXP_PRODUCT_METRICS.PERISHABLE_SALES_FLAG goes into PRODUCT_DAILY_PERFORMANCE.MARGIN_PCT, as the connector says
    cast(exp_product_metrics.margin_pct as decimal(1,0)) as perishable_sales_flag  -- FLAG crossed L2543: EXP_PRODUCT_METRICS.MARGIN_PCT goes into PRODUCT_DAILY_PERFORMANCE.PERISHABLE_SALES_FLAG, as the connector says; FLAG rounds L2543: MARGIN_PCT is computed as IIF(REVENUE=0,0,GROSS_PROFIT/REVENUE) (L2182), a double at run time because high precision is off, and is rounded to 0 decimal places by the target column PERISHABLE_SALES_FLAG decimal(1,0) (decision Q11)
from exp_product_metrics
